<script lang="ts">
 import Spooly from './Spooly.svelte';
 import PerformanceWorkspace from "./PerformanceWorkspace.svelte";
 import WhatsAppWorkspace from "./WhatsAppWorkspace.svelte";
 import SidebarToggle from "./SidebarToggle.svelte";
 import {onMount} from 'svelte';
 import {ShieldCheck,Users,Activity,Mail,LogOut,RefreshCw,Download,LockKeyhole} from '@lucide/svelte';
 import {api} from './api';
 import type {Row} from './types';
 import SignInForm from './SignInForm.svelte';
 import SetupUsers from './SetupUsers.svelte';
 import {enter, workspaceMotion} from './motion';
 import '../app.css';import '../company.css';import '../interactions.css';import '../dashboard.css';
 let user:Row|null=$state(null),data:Row|null=$state(null),ready=$state(false),busy=$state(false),error=$state(''),notice=$state('');
 let tab=$state('Overview'),search=$state(''),filter=$state('Open'),form:Row|null=$state(null),kind=$state('');
 const tabs=['Overview','Performance','Accounts','Access & new users','Issues','Email & reminders','WhatsApp'];
 let users=$derived.by(()=>(data?.users||[]).filter((u:Row)=>(u.name+' '+u.username+' '+u.email).toLowerCase().includes(search.toLowerCase())));
 let issues=$derived.by(()=>(data?.issues||[]).filter((i:Row)=>(filter==='All'||(filter==='Open'?i.status!=='Resolved':i.status===filter))&&(!search||(i.title+' '+i.route+' '+i.category+' '+(i.username||'')).toLowerCase().includes(search.toLowerCase()))));
 const time=(v:unknown)=>v?new Date(String(v)).toLocaleString():'—';
 async function load(){const result=await api('/developer');data=result;user=result.user;}
 async function signedIn(result:Row){if(!result.user.is_developer){window.location.replace('/'+result.user.portal);return;}user=result.user;await load();}
 onMount(()=>{let stopped=false;const expired=()=>{user=null;data=null;form=null;error='Please sign in again.'};window.addEventListener('erp:session-expired',expired);(async()=>{try{const s=await api('/session');if(s.user)await signedIn(s);}catch(e){error=(e as Error).message}finally{ready=true}})();const timer=setInterval(()=>{if(!stopped&&!document.hidden&&data&&!form&&!busy)load().catch(e=>error=e.message)},60000);return()=>{stopped=true;clearInterval(timer);window.removeEventListener('erp:session-expired',expired)}});
 async function logout(){try{await api('/logout',{});user=null;data=null;form=null;}catch(e){error=(e as Error).message}}
 async function refresh(){if(busy)return;busy=true;error='';try{await load()}catch(e){error=(e as Error).message}finally{busy=false}}
 function editUser(u:Row){kind='account';error='';form={id:u.id,username:u.username,name:u.name,email:u.email,phone:u.phone||'+91',is_developer:u.is_developer,mfa_enabled:u.mfa_enabled,ip_restricted:u.ip_restricted,allowed_ips:(u.allowed_ips||[]).join('\n'),version:u.version,new_password:'',password:''};}
 function removeUser(u:Row){kind='delete';error='';form={id:u.id,username:u.username,version:u.version,confirmation_username:'',password:''};}
 function editIssue(i:Row){kind='issue';error='';form={id:i.id,title:i.title,status:i.status,version:i.version,resolution:i.resolution};}
 function recipients(c?:Row){kind='recipients';error='';form={company_id:c?.id||0,name:c?.legal_name||'Additional recipients for every company',version:c?c.notification_version:data?.notification_settings.version,addresses:(c?.recipients||data?.notification_settings.recipients||[]).join('\n')};}
 function dialog(node:HTMLDialogElement){node.showModal();const motion=enter(node);return{destroy(){motion.destroy();node.close()}}}
 async function save(e:SubmitEvent){e.preventDefault();if(!form||busy)return;busy=true;error='';try{
  let result:Row;
  if(kind==='account')result=await api('/developer/users/'+form.id,{name:form.name,email:form.email,phone:form.phone,mfa_enabled:form.mfa_enabled,ip_restricted:form.ip_restricted,allowed_ips:form.allowed_ips.split(/[\n,;]/).map((s:string)=>s.trim()).filter(Boolean),new_password:form.new_password,password:form.password,version:form.version});
  else if(kind==='delete')result=await api('/developer/users/'+form.id+'/delete',{confirmation_username:form.confirmation_username,password:form.password,version:form.version});
  else if(kind==='issue')result=await api('/developer/issues/'+form.id,{status:form.status,resolution:form.resolution,version:form.version});
  else result=await api('/developer/notifications',{company_id:form.company_id,version:form.version,recipients:form.addresses.split(/[\n,;]/).map((s:string)=>s.trim()).filter(Boolean)});
  form=null;if(result.sign_in_again){user=null;data=null;notice='Your account changed. Sign in and verify your email again.';return;}
  notice='Changes saved.';await load();
 }catch(e){error=(e as Error).message}finally{busy=false}}
 function exportReport(){if(!data)return;const blob=new Blob([JSON.stringify({generated_at:new Date().toISOString(),health:data.health,worker_last_success:data.worker_last_success,issues:data.issues,flow_alerts:data.flow_alerts,reminder_delivery:data.reminders},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='euro-suits-issue-report.json';a.click();URL.revokeObjectURL(url);}
</script>
<svelte:head><title>Euro Suits · Developer</title></svelte:head>
{#if !ready}<main class="login-panel"><p role="status">Opening developer workspace…</p></main>
{:else if !user}
 <main class="login-layout"><section class="login-brand"><div class="login-brand-name"><img src="/logo.png" alt="Euro Suits logo"/><span>EURO SUITS</span></div><div><p class="eyebrow">DEVELOPER WORKSPACE</p><h1>Access.<br/>Visibility.<br/><span>Control.</span></h1><p>Account security and operational health in one place.</p></div><small>OWNER ACCESS · EMAIL VERIFICATION REQUIRED</small></section><section class="login-panel"><div class="login-form-wrap" use:enter><span class="login-symbol"><LockKeyhole size={24}/></span><h1>Developer sign in</h1><p class="muted">Enter your password, then the code sent to your personal email.</p>{#if notice}<p role="status">{notice}</p>{/if}<SignInForm portal="developer" initialUsername="developer" onauthenticated={signedIn}/>{#if error}<p class="form-error" role="alert">{error}</p>{/if}</div></section></main>
{:else}
 <div class="dev-shell erp-workspace"><a class="workspace-skip" href="#workspace-content">Skip to workspace</a><aside class="dev-sidebar"><div class="dev-brand"><img src="/logo.png" alt="Euro Suits logo"/><div><strong>EURO SUITS</strong><small>DEVELOPER</small></div></div><p class="dev-caption">OWNER WORKSPACE</p><nav aria-label="Developer navigation">{#each tabs as t}<button class:active={tab===t} aria-current={tab===t?'page':undefined} onclick={()=>{tab=t;search='';error=''}}>{#if t==='Overview'||t==='Performance'}<Activity size={18}/>{:else if t==='Accounts'||t==='Access & new users'}<Users size={18}/>{:else if t==='Issues'}<ShieldCheck size={18}/>{:else}<Mail size={18}/>{/if}{t}</button>{/each}</nav><div class="dev-owner"><strong>{user.name}</strong><small>Email verification enabled</small><button onclick={logout}><LogOut size={16}/>Sign out</button></div></aside>
 <div class="dev-main"><header class="dev-topbar"><span><SidebarToggle/>Developer / <strong>{tab}</strong></span><button class="button secondary" disabled={busy} onclick={refresh}><RefreshCw size={16}/>Refresh</button></header><main id="workspace-content" class="dev-content" tabindex="-1" use:workspaceMotion={tab}>
 {#if notice}<p class="company-notice" role="status">{notice}</p>{/if}{#if error&&!form}<p class="form-error" role="alert">{error}</p>{/if}
 {#if !data}<p role="status">Loading workspace…</p>
 {:else if tab==='Access & new users'}<SetupUsers currentUser={user}/>
 {:else}
 <div class="company-page-heading" use:enter={tab}><div><p class="eyebrow">SYSTEM ADMINISTRATION</p><h1>{tab}</h1><p>{tab==='Overview'?'Account security, application health and items needing attention.':tab==='Performance'?'Response times, database pressure and background processing.':tab==='Accounts'?'Manage account details and sign-in security. Employees cannot edit their own accounts.':tab==='Issues'?'Captured errors and suspicious activity signals. Review, investigate and record the fix.':'Company email delivery and renewal notification recipients.'}</p></div>{#if tab==='Issues'}<button class="button secondary" onclick={exportReport}><Download size={16}/>Export report</button>{/if}</div>
 {#if tab==='Overview'}
 <div class="dev-stats"><article class="panel"><small>Active accounts</small><strong>{data.users.filter((u:Row)=>u.active&&!u.deleted_at).length}</strong></article><article class="panel"><small>Two-step verification</small><strong>{data.users.filter((u:Row)=>u.mfa_enabled&&!u.deleted_at).length}</strong></article><article class="panel"><small>Recent unresolved issues</small><strong>{data.issues.filter((i:Row)=>i.status!=='Resolved').length}</strong></article><article class="panel"><small>Flow alerts</small><strong>{data.flow_alerts.length}</strong></article></div>
 <section class="panel dev-section"><h2>Service health</h2><div class="dev-health">{#each [['Database',data.health.database],['Session store',data.health.redis],['Email sender',data.health.email_configured]] as service}<div><span>{service[0]}</span><strong class:dev-warning={!service[1]}>{service[1]?(service[0]==='Email sender'?'Settings present':'Ready'):'Needs attention'}</strong></div>{/each}<div><span>Reminder worker</span><strong class:dev-warning={!data.worker_last_success||Date.now()/1000-data.worker_last_success>180}>{data.worker_last_success?time(new Date(data.worker_last_success*1000).toISOString()):'No successful run recorded'}</strong></div></div>{#if !data.health.email_configured}<p class="company-warning">The company email sender still needs its server credentials. Accounts with two-step verification cannot sign in until email delivery works.</p>{/if}</section>
 <section class="panel dev-section"><h2>Workflow checks</h2>{#each data.flow_alerts as alert}<p><strong>{alert.po}</strong> · {alert.stage} · {alert.issue}</p>{:else}<p class="muted">No missing work-item records detected in approved orders.</p>{/each}<p class="muted">These checks identify specific inconsistencies. New or unreported workflow defects still need investigation.</p></section>
 <section class="panel dev-section"><h2>Recent account activity</h2>{#each data.history.slice(0,10) as h}<div class="dev-history"><strong>{h.action}</strong><span>{h.actor} · {h.subject_type} #{h.subject_id}</span><small>{time(h.created_at)}</small></div>{:else}<p class="muted">No activity recorded.</p>{/each}</section>
 {:else if tab==='Performance'}<PerformanceWorkspace/>
 {:else if tab==='WhatsApp'}<WhatsAppWorkspace/>
 {:else if tab==='Accounts'}
 <section class="panel"><div class="company-register-toolbar"><input aria-label="Search accounts" bind:value={search} placeholder="Search name, username or email"/><button class="button primary" onclick={()=>tab='Access & new users'}>Add user / manage access</button></div><div class="table-wrap"><table><thead><tr><th>Account</th><th>Role</th><th>Email</th><th>Security</th><th>Actions</th></tr></thead><tbody>{#each users as u}<tr><td><strong>{u.name}</strong><br/><small>{u.username}</small></td><td>{u.is_developer?'Developer owner':u.designation||u.role}</td><td>{u.email||'Not assigned'}<br/><small>{u.phone}</small></td><td>{u.deleted_at?'Deleted':u.active?'Active':'Disabled'}<br/><small>{u.mfa_enabled?'Email OTP enabled':'Password only'}</small><small>{u.is_developer?'Any IP · developer owner':u.ip_restricted?'IP restricted · '+u.allowed_ips.length+' entries':'Any IP'}</small></td><td>{#if !u.deleted_at}<div class="row-actions"><button class="button secondary" onclick={()=>editUser(u)}>Account settings</button>{#if !u.is_developer}<button class="text-button danger" onclick={()=>removeUser(u)}>Delete</button>{/if}</div>{/if}</td></tr>{/each}</tbody></table></div></section>
 {:else if tab==='Issues'}
 <section class="panel"><div class="company-register-toolbar"><div class="filter-tabs">{#each ['Open','Investigating','Resolved','All'] as value}<button class:active={filter===value} onclick={()=>filter=value}>{value}</button>{/each}</div><input aria-label="Search issues" bind:value={search} placeholder="Search issue, user or endpoint"/></div><div class="table-wrap"><table><thead><tr><th>Issue</th><th>Location / user</th><th>Occurrences</th><th>Last seen</th><th>Status</th></tr></thead><tbody>{#each issues as i}<tr><td><strong>{i.title}</strong><br/><small>{i.category} · {i.severity}{i.http_status?' · HTTP '+i.http_status:''}</small></td><td><code>{i.route}</code><br/><small>{i.username||'Anonymous / background service'}</small>{#if i.request_id}<details><summary>Request ID</summary><code>{i.request_id}</code></details>{/if}</td><td>{i.occurrences}</td><td>{time(i.last_seen)}</td><td><button class="button secondary" onclick={()=>editIssue(i)}>{i.status}</button></td></tr>{:else}<tr><td colspan="5">No matching issues.</td></tr>{/each}</tbody></table></div></section><p class="muted">Repeated events are grouped. A new occurrence reopens a resolved issue. Security signals can include normal failed logins; they are not proof of an attack. The list contains up to 200 recent issue groups.</p>
 {:else if tab==='Email & reminders'}
 <section class="panel dev-section"><h2>Email sender</h2><p><strong>{data.health.email_sender||'Not configured'}</strong> · {data.health.smtp_host||'No server'}:{data.health.smtp_port||'587'}</p><p>{data.health.email_configured?'Sender settings are present. Delivery status is shown below.':'Server authentication is missing. Configure the private SMTP settings before testing OTP delivery.'}</p><p class="muted">SMTP passwords and Microsoft application secrets are kept in the server configuration and are never displayed here.</p></section>
 <section class="panel dev-section"><div class="detail-card-heading"><h2>Additional recipients for every company</h2><button class="button secondary" onclick={()=>recipients()}>Change recipients</button></div><p>{data.notification_settings.recipients.join(', ')||'None'}</p><p class="muted">These addresses also receive every company renewal reminder. Company overrides below replace that company's original renewal recipients. An empty override uses its original recipients.</p></section>
 <section class="panel dev-section"><h2>Company reminder recipients</h2>{#each data.companies as c}<div class="dev-history"><strong>{c.legal_name}</strong><span>{c.recipients.join(', ')||'Use recipients from the company record'}</span><button class="button secondary" onclick={()=>recipients(c)}>Change</button></div>{:else}<p class="muted">Companies will appear after registration.</p>{/each}</section>
 <section class="panel dev-section"><h2>Delivery status</h2>{#each data.reminders as r}<div class="dev-history"><strong>{r.legal_name} · {r.label}</strong><span>{r.email_status} {r.last_error?'— '+r.last_error:''}</span><small>Next attempt: {time(r.next_attempt)}</small></div>{:else}<p class="muted">No active renewal reminders.</p>{/each}</section>
 {/if}{/if}
 </main></div></div>
{/if}
{#if form}<dialog use:dialog class="company-modal" aria-label={kind==='account'?'Account settings':kind==='delete'?'Delete user':kind==='issue'?'Issue review':'Reminder recipients'} oncancel={e=>{if(busy)e.preventDefault();else form=null}}><header><h2>{kind==='account'?'Account settings':kind==='delete'?'Delete user':kind==='issue'?'Issue review':'Reminder recipients'}</h2><button class="button secondary" disabled={busy} onclick={()=>form=null}>Close</button></header><form onsubmit={save}>
 {#if kind==='account'}<p><strong>{form.username}</strong> · Changes revoke this account's existing sessions.</p><div class="company-form-grid"><label>Full name<input bind:value={form.name} required maxlength="120"/></label><label>Phone<input bind:value={form.phone} maxlength="50"/></label><label class="wide">Email for verification<input type="email" bind:value={form.email} required={form.mfa_enabled} disabled={form.is_developer} maxlength="254"/></label><label class="inline-check wide"><input type="checkbox" bind:checked={form.mfa_enabled} disabled={form.is_developer}/>Require two-step email verification</label>{#if form.is_developer}<p class="wide muted">Developer access works from any IP. Email verification is always required.</p>{:else}<label class="inline-check wide"><input type="checkbox" bind:checked={form.ip_restricted}/>Restrict sign-in to allowed IP addresses</label><label class="wide">Allowed public IPs or network ranges<textarea bind:value={form.allowed_ips} rows="4" placeholder="203.0.113.10&#10;2001:db8::/64"></textarea><small>One IPv4, IPv6 or CIDR range per line. Your current public IP: {data?.current_ip}. Restrictions also apply to existing sessions and Super Admin accounts.</small></label>{/if}<label class="wide">New account password<input type="password" bind:value={form.new_password} autocomplete="new-password" maxlength="128"/><small>Leave blank to keep the current password. {data?.local?'1234 is allowed for local testing.':'Use 12–128 characters.'}</small></label><label class="wide">Your developer password<input type="password" bind:value={form.password} required autocomplete="current-password" maxlength="128"/></label></div><p class="muted">Sensitive changes require an email-verified sign-in within the last 15 minutes.</p>
 {:else if kind==='delete'}<p class="company-warning">Deleting {form.username} immediately blocks sign-in and retains their work and audit history. Use employee replacement first when unfinished responsibilities need transfer.</p><label>Type the exact username: {form.username}<input bind:value={form.confirmation_username} required autocomplete="off"/></label><label>Your developer password<input type="password" bind:value={form.password} required autocomplete="current-password" maxlength="128"/></label>
 {:else if kind==='issue'}<p>{form.title}</p><label>Status<select bind:value={form.status}><option>Open</option><option>Investigating</option><option>Resolved</option></select></label><label>Investigation / resolution note<textarea bind:value={form.resolution} maxlength="2000" required={form.status==='Resolved'} rows="5" placeholder="What happened, what you checked and how it was fixed"></textarea></label>
 {:else}<p>{form.name}</p><label>Reminder email addresses<textarea bind:value={form.addresses} rows="5" maxlength="2500" placeholder="One email address per line"></textarea></label>{/if}
 {#if error}<p class="form-error" role="alert">{error}</p>{/if}<footer><button type="button" class="button secondary" disabled={busy} onclick={()=>form=null}>Cancel</button><button class="button primary" disabled={busy||(kind==='delete'&&form.confirmation_username!==form.username)}>{busy?'Saving…':kind==='delete'?'Delete user':'Save changes'}</button></footer></form></dialog>{/if}

<style>
 .dev-shell{display:flex;min-height:100vh;background:#f5f6f8}.dev-sidebar{width:244px;background:#13242c;color:#e8eef1;padding:28px 18px;display:flex;flex-direction:column;position:sticky;top:0;height:100vh;flex-shrink:0}.dev-brand{display:flex;gap:12px;align-items:center;padding:0 10px 32px}.dev-brand img{width:40px;height:40px;object-fit:contain;border-radius:8px;background:#000}.dev-brand small,.dev-owner small{display:block;font-size:10px;letter-spacing:1.5px;margin-top:6px;color:#aab8bf}.dev-caption{font-size:10px;letter-spacing:1.5px;padding:0 12px;color:#8fa2ad}.dev-sidebar nav{display:grid;gap:6px}.dev-sidebar button{display:flex;align-items:center;gap:10px;border:0;background:transparent;color:#bbcad1;padding:13px 12px;text-align:left;border-radius:8px;font:inherit;font-size:13px;cursor:pointer}.dev-sidebar button.active{background:#29414a;color:white}.dev-sidebar button:hover{background:#233740}.dev-owner{margin-top:auto;padding:28px 12px 0}.dev-owner button{padding-left:0;margin-top:15px}.dev-main{min-width:0;flex:1}.dev-topbar{display:flex;justify-content:space-between;align-items:center;padding:18px 32px;border-bottom:1px solid #e2e6e9;background:#fff;color:#667680;font-size:13px}.dev-content{padding:28px 32px;max-width:1600px;margin:auto}.dev-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:24px}.dev-stats article{padding:22px}.dev-stats small{display:block;color:#687782}.dev-stats strong{display:block;font-size:32px;margin-top:10px;letter-spacing:-1px}.dev-section{padding:24px;margin-bottom:20px}.dev-section h2{font-size:17px;margin:0 0 18px}.dev-health{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.dev-health div{display:grid;gap:7px;font-size:13px}.dev-health span{color:#687782}.dev-health strong{color:#24735a}.dev-health strong.dev-warning{color:#966119}.dev-history{display:flex;align-items:center;gap:16px;padding:14px 0;border-top:1px solid #e9ecef;font-size:12px}.dev-history strong{flex:1}.dev-history span,.dev-history small{color:#667680}.dev-content code{font-size:11px;overflow-wrap:anywhere}.dev-content td{vertical-align:top}.dev-content .muted{line-height:1.65}.dev-content .company-page-heading h1{font-size:28px}
 @media(max-width:1050px){.dev-sidebar{width:210px}.dev-content{padding:24px}.dev-stats{grid-template-columns:repeat(2,1fr)}.dev-history{flex-wrap:wrap}.dev-history strong{flex-basis:100%}}
 @media(max-width:700px){.dev-shell{display:block}.dev-sidebar{width:auto;height:auto;position:static;padding:16px}.dev-brand{padding:0 0 12px}.dev-caption,.dev-owner small{display:none}.dev-sidebar nav{display:flex;overflow-x:auto}.dev-sidebar nav button{white-space:nowrap}.dev-owner{padding:12px 0 0;display:flex;justify-content:space-between;align-items:center}.dev-owner button{margin:0;padding:8px}.dev-topbar{padding:12px 16px}.dev-content{padding:20px 16px}.dev-health{grid-template-columns:1fr}.dev-stats{gap:10px}.dev-stats article{padding:16px}.dev-content input{min-width:0}}
</style>

{#if ready && user && data}
 <Spooly userId={user.id} role={user.role} portal="developer" page={tab}/>
{/if}
